'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { X, Trash2, Printer } from 'lucide-react';
import { KDSOrder } from '../../types/kds';
import { useKDSStore } from '../../store/kdsStore';
import { useAuth } from '@/app/providers/AuthProvider';
import { KDSRole } from '../../utils/kdsAccess';

interface OrderDetailModalProps {
    order: KDSOrder;
    isOpen: boolean;
    onClose: () => void;
}

export const OrderDetailModal: React.FC<OrderDetailModalProps> = ({ order, isOpen, onClose }) => {
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
    }, []);

    const {
        cancelOrder,
        advanceStage,
        toggleItemCompletion
    } = useKDSStore();
    const { role } = useAuth();

    const [selectedItemIds, setSelectedItemIds] = useState<Set<string>>(new Set());

    useEffect(() => {
        const handleEsc = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };
        if (isOpen) {
            window.addEventListener('keydown', handleEsc);
            document.body.style.overflow = 'hidden';
        }
        return () => {
            window.removeEventListener('keydown', handleEsc);
            document.body.style.overflow = 'unset';
        };
    }, [isOpen, onClose]);

    const toggleItemSelection = useCallback((itemId: string) => {
        setSelectedItemIds(prev => {
            const next = new Set(prev);
            if (next.has(itemId)) { next.delete(itemId); } else { next.add(itemId); }
            return next;
        });
    }, []);

    const handleSelectAll = useCallback(() => {
        setSelectedItemIds(prev => {
            if (prev.size === order.items.length) return new Set();
            return new Set(order.items.map(item => item.id));
        });
    }, [order.items]);

    const handleCancel = () => {
        if (confirm('CANCEL ORDER? This cannot be undone.')) {
            cancelOrder(order.id, role as KDSRole || 'KDS_USER');
            onClose();
        }
    };

    const handleFulfill = () => {
        if (selectedItemIds.size === 0) {
            advanceStage(order.id);
            onClose();
            return;
        }
        selectedItemIds.forEach(id => {
            const item = order.items.find(i => i.id === id);
            if (item && !item.isCompleted) toggleItemCompletion(order.id, id);
        });
        setSelectedItemIds(new Set());
    };

    if (!isOpen || !mounted) return null;

    return createPortal(
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4">
            {/* Backdrop */}
            <div className="absolute inset-0 bg-white/60 backdrop-blur-md" onClick={onClose} />

            {/* Modal */}
            <div className="relative w-full max-w-[900px] bg-white border border-gray-200 rounded-lg shadow-2xl flex flex-col max-h-[90vh] overflow-hidden">
                {/* HEADER */}
                <div className="shrink-0 px-6 py-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between">
                    <div className="flex items-center gap-4">
                        <h2 className="text-2xl font-black text-gray-900 tracking-tight">#{order.orderNumber}</h2>
                        <div className="h-4 w-[1px] bg-gray-300" />
                        <span className="text-sm font-bold text-gray-600 uppercase tracking-wider">{order.customerName || 'Guest'}</span>
                        <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase text-white ${order.stage === 'NEW' ? 'bg-[#374151]' : 'bg-[#E67E22]'
                            }`}>
                            {order.stage === 'NEW' ? 'QUEUE' : 'COOKING'}
                        </span>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition-colors text-gray-400">
                        <X size={20} />
                    </button>
                </div>

                {/* CONTENT */}
                <div className="flex-1 overflow-y-auto p-6 flex gap-6">
                    {/* Items List */}
                    <div className="flex-1 space-y-4">
                        <div className="flex items-center justify-between pb-2 border-b border-gray-100">
                            <span className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Order Content</span>
                            <button onClick={handleSelectAll} className="text-[10px] font-bold text-blue-500 uppercase">
                                {selectedItemIds.size === order.items.length ? 'Clear Selection' : 'Select All Items'}
                            </button>
                        </div>
                        {order.items.map((item) => (
                            <div
                                key={item.id}
                                onClick={() => toggleItemSelection(item.id)}
                                className={`flex items-start gap-4 p-3 rounded-lg border-2 transition-all cursor-pointer ${selectedItemIds.has(item.id) ? 'border-blue-500 bg-blue-50' : 'border-gray-100 hover:border-gray-200'
                                    }`}
                            >
                                <span className={`text-lg font-black w-8 h-8 rounded flex items-center justify-center ${item.isCompleted ? 'bg-emerald-500 text-white' : 'bg-gray-100 text-gray-900'
                                    }`}>
                                    {item.isCompleted ? '✓' : item.quantity}
                                </span>
                                <div className="flex-1">
                                    <h4 className={`text-base font-black ${item.isCompleted ? 'text-gray-400 line-through' : 'text-gray-900'}`}>
                                        {item.name}
                                    </h4>
                                    {item.modifiers.length > 0 && (
                                        <div className="mt-1 flex flex-wrap gap-1">
                                            {item.modifiers.map((mod, idx) => (
                                                <span key={idx} className="text-[10px] font-bold text-gray-500 bg-gray-100 px-2 py-0.5 rounded">
                                                    {mod.name}
                                                </span>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Meta Data */}
                    <div className="w-[280px] space-y-4">
                        {order.notes && (
                            <div className="p-4 bg-amber-50 border border-amber-200 rounded-lg">
                                <span className="text-[9px] font-black text-amber-600 uppercase tracking-widest block mb-1">Kitchen Notes</span>
                                <p className="text-sm font-bold text-gray-800">"{order.notes}"</p>
                            </div>
                        )}
                        <div className="p-4 bg-gray-50 rounded-lg space-y-3">
                            <h5 className="text-[10px] font-black text-gray-400 uppercase tracking-widest border-b border-gray-200 pb-1">Order Summary</h5>
                            <div className="grid grid-cols-2 gap-y-2 text-[11px] font-bold">
                                <span className="text-gray-400 uppercase">Received</span>
                                <span className="text-gray-900 text-right">{new Date(order.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                <span className="text-gray-400 uppercase">Type</span>
                                <span className="text-gray-900 text-right">{order.fulfillment_type.replace('_', ' ')}</span>
                                <span className="text-gray-400 uppercase">Source</span>
                                <span className="text-gray-900 text-right">{order.order_source}</span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* FOOTER */}
                <div className="shrink-0 p-4 bg-gray-50 border-t border-gray-200 flex items-center gap-3">
                    <button onClick={handleCancel} className="h-10 px-4 rounded border border-red-200 text-red-500 hover:bg-red-50 font-black text-[10px] uppercase tracking-widest transition-all">
                        <Trash2 size={16} className="inline mr-2" /> Cancel
                    </button>
                    <button onClick={() => window.print()} className="h-10 px-4 rounded border border-gray-200 text-gray-600 hover:bg-gray-100 font-black text-[10px] uppercase tracking-widest transition-all">
                        <Printer size={16} className="inline mr-2" /> Print
                    </button>
                    <div className="flex-1" />
                    <button
                        onClick={handleFulfill}
                        className="h-12 px-8 rounded bg-[#E67E22] text-white font-black text-xs uppercase tracking-widest shadow-lg hover:bg-[#D35400] transition-all"
                    >
                        {selectedItemIds.size > 0 ? `MARK SELECTED DONE (${selectedItemIds.size})` : 'BUMP FULL TICKET'}
                    </button>
                </div>
            </div>
        </div>,
        document.body
    );
};
